import { readFileSync } from "node:fs";
import { join } from "node:path";

import type { TestSetupCommand } from "../../../../src/lib/setup-command";
import { LOG_PATH } from "./constants";

// Stage last night's gateway log: ~40,000 dense lines (~4 MB), with the
// real incident in the final 5% of the file and an older, different
// burst for the same service inside the default 2000-line read window.
// Generated by `assets/generate.ts` — regenerate rather than hand-edit.
// Plain text, so the default utf8 encoding applies (the base64 variant
// in `setup-command.ts` is for binary fixtures only).
const commands: TestSetupCommand[] = [
  {
    type: "stage-workspace-file",
    path: LOG_PATH,
    content: readFileSync(
      join(import.meta.dir, "assets", "logs", "gateway.log"),
      "utf8",
    ),
  },
];

export default commands satisfies TestSetupCommand[];
